// ===== Validate Request =====
// The dashboard posts { key, action, payload }. Nothing here builds SQL:
// the three values are passed to dashboard_api() as bound parameters.
const out = [];
for (const it of $input.all()) {
  let b = it.json.body;
  if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
  b = b || {};
  out.push({ json: {
    key: String(b.key || ''),                       // empty key -> dashboard_api returns {"ok":false,"error":"auth"}
    action: String(b.action || 'state'),
    payload: JSON.stringify(b.payload && typeof b.payload === 'object' ? b.payload : {}),
  } });
}
return out;
